INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('studentenheime-foerderung-2027-bund-10-millionen-euro','Studentenheime: Ab 2027 wieder 10 Millionen Euro Förderung','Nach rund 16 Jahren Pause will der Bund gemeinnützige Studentenheime wieder fördern: Ab 2027 sind 10 Millionen Euro pro Jahr vorgesehen. Die Heimplätze sind seit 2015 um 61 Prozent teurer geworden.','Studentenheime in Österreich sollen ab 2027 wieder Geld vom Bund bekommen. Wie Wissenschaftsministerin Eva-Maria Holzleitner (SPÖ) bekanntgegeben hat, stellt die Bundesregierung künftig zehn Millionen Euro pro Jahr für gemeinnützige Studierendenheime bereit. Mit den Mitteln sollen leistbare Wohnplätze neu entstehen und bestehende erhalten bleiben. Öffentlich gemacht wurde die Ankündigung am 30. Oktober über den SPÖ-Parlamentsklub.

## Studentenheime: Förderung nach 16 Jahren zurück

Eine eigene Bundesförderung für Heimplätze gibt es seit rund 16 Jahren nicht mehr. Sie war im Zuge des Sparpakets rund um das Jahr 2010 ausgelaufen. Davor hatte das Wissenschaftsministerium sowohl Neubauten als auch Sanierungen von Studentenheimen mitfinanziert. Laut damaligen Berichten von FM4 lag der Zuschuss bei Sanierungen bei bis zu 11.000 Euro pro Heimplatz, bei Neubauten bei bis zu 15.000 Euro.

Seit dem Wegfall mussten die meist gemeinnützigen Heimträger Investitionen weitgehend aus eigener Kraft oder über Länderförderungen stemmen. Medienberichte dokumentierten schon früh Fälle, in denen bereits geplante Generalsanierungen ohne Bundeszuschuss nicht umgesetzt werden konnten. Die Wiedereinführung der Förderung war bereits im aktuellen Regierungsprogramm angekündigt. Holzleitner hatte die Kostenentwicklung im Frühjahr als Alarmsignal bezeichnet.

## Was ein Heimplatz heute kostet

Hintergrund der Entscheidung sind die stark gestiegenen Wohnkosten für Studierende. Die Zahlen stammen aus der Studierenden-Sozialerhebung 2025:

- Ein Platz im Studierendenheim kostet im Schnitt **501 Euro pro Monat**.
- Das ist um 61 Prozent mehr als im Jahr 2015 und damit der stärkste Anstieg aller Wohnformen.
- Insgesamt geben Studierende durchschnittlich 586 Euro monatlich fürs Wohnen aus, das sind rund 38 Prozent ihres Budgets.
- Etwa ein Viertel der Studierenden berichtet weiterhin von ernsthaften finanziellen Schwierigkeiten.

Gerade für Studienanfängerinnen und Studienanfänger aus den Bundesländern ist ein Heimplatz oft die erste eigene Bleibe in der Uni-Stadt. SPÖ-Wissenschaftssprecher Heinrich Himmer formulierte es so: Studi-Heime seien für viele „das erste eigene Zuhause“, das leistbar sein müsse.

## Was noch offen ist

Wie die zehn Millionen Euro konkret verteilt werden, ist bisher nicht bekannt. Offen sind unter anderem diese Punkte:

1. Ob das Geld vorrangig in Neubau, in Sanierungen oder in beides fließt.
2. Welche Voraussetzungen Heimträger erfüllen müssen, etwa Mietobergrenzen oder Bindungsfristen.
3. Wie die Förderung beantragt wird und ab wann Anträge möglich sind.

Eine eigene Förderrichtlinie des Ministeriums lag zum Zeitpunkt der Ankündigung noch nicht vor. Zum Vergleich: Mit früheren Zuschüssen von bis zu 15.000 Euro pro Neubauplatz ließen sich mit zehn Millionen Euro rechnerisch einige hundert Plätze pro Jahr unterstützen. Wie hoch die Fördersätze künftig ausfallen, bleibt abzuwarten.

## Was Studierende jetzt tun können

An den Mieten für das laufende Studienjahr ändert die Ankündigung vorerst nichts, da die Mittel erst ab 2027 fließen. Wer einen Heimplatz sucht, sollte sich früh bei mehreren Trägern bewerben, da Plätze in Uni-Städten wie Wien, Graz, Innsbruck oder Salzburg begehrt sind. Zusätzlich lohnt ein Blick auf die Studienbeihilfe und auf Wohnbeihilfen der Länder, die je nach Bundesland auch Heimbewohnerinnen und Heimbewohnern offenstehen können.

Presseinfo berichtet weiter, sobald die Details zur Vergabe der neuen Bundesförderung für Studentenheime veröffentlicht sind.','bauen-wohnen','Bauen',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/studentenheime-foerderung-2027-bund-10-millionen-euro.webp','SPÖ-Parlamentsklub (APA-OTS)','https://www.ots.at/presseaussendung/OTS_20261030_OTS0032/spoe-himmer-zur-neuen-foerderung-fuer-studierendenwohnheime-erstes-zuhause-muss-leistbar-sein','published','2026-11-01T06:55:00.000Z','2026-11-01T06:45:19.650Z','Studentenheime: Bundesförderung ab 2027 wieder da','Studentenheime erhalten ab 2027 wieder Bundesförderung: 10 Millionen Euro pro Jahr für gemeinnützige Heime. Was bekannt ist und was noch offen ist.','Studentenheime','["Studentenheime","Studierendenheime Förderung","Studentenheim Kosten","Bundesförderung Studentenheime 2027","leistbares Wohnen Studierende","Heimplatz Preis Österreich","Studierenden-Sozialerhebung 2025","gemeinnützige Studierendenheime"]','Studentenheime in Österreich: modernes Studierendenheim mit Fahrrädern im Herbst','Modern student residence building in an Austrian university city at early morning, timber and glass facade, bicycles parked in front, autumn trees with yellow leaves, a few lit windows, realistic architecture photography, no text, no logos, no readable signs, no people in focus','[{"q":"Wie viel Geld gibt es ab 2027 für Studentenheime?","a":"Der Bund stellt laut Wissenschaftsministerin Holzleitner ab 2027 zehn Millionen Euro pro Jahr für gemeinnützige Studierendenheime bereit."},{"q":"Was kostet ein Heimplatz derzeit?","a":"Laut Studierenden-Sozialerhebung 2025 im Schnitt 501 Euro pro Monat, um 61 Prozent mehr als 2015."},{"q":"Wann kann man die Förderung beantragen?","a":"Die Vergaberegeln und das Antragsverfahren sind noch nicht veröffentlicht. Die Mittel sollen ab 2027 fließen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded